inventa_destino_fisico":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22x08_evalua_pertenencia_segmento":false,"s22x08_multiples_segmentos_activos":true,"s22x08_reasigna_sin_historia_o_auditoria":true,"s22x08_muta_cartera":true,"s22x08_avanza_con_deuda_sin_segmento":true,"s22x08_inventa_destino_fisico":true},"esperado":false}]},"hash":"eb40869870e73e06507ee3350f43f3780216b52a0d6e844dce9b83ce8cdb05d5","hash_paquete":"6dd994ab9c422945112f274b252c8b660842ebc2d7acfdf90ac0be5a019ff9dd","hash_evaluado":"eb40869870","hash_paquete_10":"6dd994ab9c","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22X-C09","legacy_id":684,"legacy_ids":[684],"relacionadas":["S22Q-C04","S22W-C09"],"residual":"","coberturas":[{"legacy_id":684,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Contrato fuente íntegro en descripción de S22X-C09; conserva semántica y referencias literales, sin habilitar runtime."}],"hechos":["s22x09_evalua_decision_segmento","s22x09_estado_no_catalogado","s22x09_avance_pendiente","s22x09_bloquea_estado_resuelto","s22x09_sin_oferta_automatico_o_segmento","s22x09_decision_sin_auditoria"],"paquete":{"tipo":"NUEVA","codigo":"S22X-C09","clave":"s22x_legacy_684","familia":"STATES","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"B2B","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Decisión comercial explícita por segmento","descripcion":"BLOQUEAR incumplimiento del contrato funcional B2B-RULE-OFFER-SEGMENT-DECISION-001 en B2B. Al llegar a la etapa de Oferta, cada segmento debe tener una decisión comercial explícita. Los estados funcionales son: CON_OFERTA cuando existe una oferta configurada; SIN_OFERTA cuando la empresa decide explícitamente no ofrecer condiciones al segmento; y PENDIENTE mientras no exista una decisión. Solo PENDIENTE bloquea el avance. SIN_OFERTA no es un segmento ni una asignación automática y debe quedar trazado como decisión de la empresa. Referencias literales del contrato fuente (no nuevas configuraciones ni autorización de implementación): {\"screen_code\":\"B2B-OFERTA-001\",\"blocking_states\":[\"PENDIENTE\"],\"no_offer_is_segment\":false,\"non_blocking_states\":[\"CON_OFERTA\",\"SIN_OFERTA\"],\"allowed_decision_states\":[\"CON_OFERTA\",\"SIN_OFERTA\",\"PENDIENTE\"],\"decision_audit_required\":true,\"physical_state_model_status\":\"PENDING_FUNCTIONAL_DEFINITION\",\"automatic_no_offer_assignment\":\"DENY\",\"no_offer_requires_explicit_company_decision\":true}. Los estados pendientes y restricciones de creación física se conservan; binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/684","solicitante":"Cristhian / Claude S22-X 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22x09_evalua_decision_segmento"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22x09_estado_no_catalogado"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22x09_avance_pendiente"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22x09_bloquea_estado_resuelto"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22x09_sin_oferta_automatico_o_segmento"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22x09_decision_sin_auditoria"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22x09_evalua_decision_segmento":true,"s22x09_estado_no_catalogado":false,"s22x09_avance_pendiente":false,"s22x09_bloquea_estado_resuelto":false,"s22x09_sin_oferta_automatico_o_segmento":false,"s22x09_decision_sin_auditoria":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22x09_evalua_decision_segmento":true,"s22x09_estado_no_catalogado":true,"s22x09_avance_pendiente":false,"s22x09_bloquea_estado_resuelto":false,"s22x09_sin_oferta_automatico_o_segmento":false,"s22x09_decision_sin_auditoria":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22x09_evalua_decision_segmento":true,"s22x09_estado_no_catalogado":false,"s22x09_avance_pendiente":true,"s22x09_bloquea_estado_resuelto":false,"s22x09_sin_oferta_automatico_o_segmento":false,"s22x09_decision_sin_auditoria":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22x09_evalua_decision_segmento":true,"s22x09_estado_no_catalogado":false,"s22x09_avance_pendiente":false,"s22x09_bloquea_estado_resuelto":true,"s22x09_sin_oferta_automatico_o_segmento":false,"s22x09_decision_sin_auditoria":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22x09_evalua_decision_segmento":true,"s22x09_estado_no_catalogado":false,"s22x09_avance_pendiente":false,"s22x09_bloquea_estado_resuelto":false,"s22x09_sin_oferta_automatico_o_segmento":true,"s22x09_decision_sin_auditoria":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22x09_evalua_decision_segmento":true,"s22x09_estado_no_catalogado":false,"s22x09_avance_pendiente":false,"s22x09_bloquea_estado_resuelto":false,"s22x09_sin_oferta_automatico_o_segmento":false,"s22x09_decision_sin_auditoria":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22x09_evalua_decision_segmento":false,"s22x09_estado_no_catalogado":true,"s22x09_avance_pendiente":true,"s22x09_bloquea_estado_resuelto":true,"s22x09_sin_oferta_automatico_o_segmento":true,"s22x09_decision_sin_auditoria":true},"esperado":false}]},"hash":"6316d2e35bada6536bba92e4d0e9b3fefaa6ed49fff96d6091672c2418d41184","hash_paquete":"c12363e9ac1aca86ddfe968996c2b8b2cd1df13dcbc77c4c4b243de8d5f01165","hash_evaluado":"6316d2e35b","hash_paquete_10":"c12363e9ac","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-26 19:20 Lima: evaluador independiente 65/65, descripción y valor_config comparados con referencias literales');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22X_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22X_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22X_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22X_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22X_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-26 19:20 Lima'),h,'GPT / Claude S22-X independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22X_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22X_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22X_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22X_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $s22$;
COMMIT;
